    public static <T> Class<T> primitiveTypeOf(Class<T> clazz) {
        if (!clazz.isPrimitive()) {
            return (Class<T>) PRIMITIVE_BY_WRAPPER.get(clazz);
        }
        return clazz;
    }

    public static boolean isPrimitiveWrapper(Class<?> type) {
        return WRAPPER_DEFAULTS.containsKey(type);
    }

    public static <T> T primitiveWrapperOf(Class<T> type) {
        return (T) WRAPPER_DEFAULTS.get(type);
    }

    public static <T> T primitiveValueOrNullFor(Class<T> primitiveType) {
        return (T) PRIMITIVE_DEFAULTS.get(primitiveType);
    }
    private static Map<Class<?>, Class<?>> UNUSED_WRAPPER_TYPES = new HashMap<Class<?>, Class<?>>();
    private static Map<Class<?>, Class<?>> PRIMITIVE_BY_WRAPPER = new HashMap<Class<?>, Class<?>>();
    private static Map<Class<?>, Object> WRAPPER_DEFAULTS = new HashMap<Class<?>, Object>();
    private static Map<Class<?>, Object> PRIMITIVE_DEFAULTS = new HashMap<Class<?>, Object>();

    static {
        Class<?>[][] pairs = new Class<?>[][] {
